# igmp-snoop-decode：在 stp-decode（stp-check 七键）配置上追加 igmp 对象
IGMP_SNOOP_CONFIG_KEYS = STP_CHECK_CONFIG_KEYS | frozenset(("igmp",))
IGMP_KEYS = frozenset(("membership_age", "router_ports"))
IPV4_ETHER_TYPE = 0x0800
IP_PROTOCOL_IGMP = 2
IGMP_TYPE_QUERY_V2 = 0x11
IGMP_TYPE_REPORT_V2 = 0x16
IGMP_TYPE_LEAVE_V2 = 0x17
IGMP_TYPE_REPORT_V3 = 0x22
IGMP_CONTROL_ACTIONS = {
    IGMP_TYPE_QUERY_V2: "igmp_query",
    IGMP_TYPE_REPORT_V2: "igmp_report",
    IGMP_TYPE_LEAVE_V2: "igmp_leave",
}
# IGMPv3 Membership Report 组记录类型
IGMPV3_MODE_IS_INCLUDE = 1
IGMPV3_MODE_IS_EXCLUDE = 2
IGMPV3_CHANGE_TO_INCLUDE = 3
IGMPV3_CHANGE_TO_EXCLUDE = 4
IGMPV3_ALLOW_NEW_SOURCES = 5
IGMPV3_BLOCK_OLD_SOURCES = 6
IGMPV3_RECORD_TYPES = frozenset(range(1, 7))
IPV4_MC_MAC_PREFIX = b"\x01\x00\x5e"


def validate_igmp_snoop_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != IGMP_SNOOP_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # 七键与 stp-decode（stp-check）完全一致，复用其全量校验
    bridges, links, delay, bridge, ports, age, max_frame = (
        validate_stp_check_config(
            {key: config[key] for key in STP_CHECK_CONFIG_KEYS}
        )
    )
    igmp = config["igmp"]
    if not isinstance(igmp, dict) or frozenset(igmp) != IGMP_KEYS:
        raise InvalidInput("bad igmp")
    membership_age = igmp["membership_age"]
    if not _is_int(membership_age) or membership_age <= 0:
        raise InvalidInput("bad igmp membership_age")
    router_ports = igmp["router_ports"]
    if not isinstance(router_ports, list):
        raise InvalidInput("bad igmp router_ports")
    name_set = {port["name"] for port in ports}
    for name in router_ports:
        if not isinstance(name, str) or name not in name_set:
            raise InvalidInput("bad igmp router port")
    if len(set(router_ports)) != len(router_ports):  # 端口名不重复
        raise InvalidInput("bad igmp router_ports")
    return (
        bridges, links, delay, bridge, ports, age, max_frame,
        membership_age, tuple(router_ports),
    )


def _internet_checksum(data):
    """IPv4/IGMP 反码求和校验；奇数尾字节补零，校验时整段求和须为 0。"""
    if len(data) % 2:
        data = data + b"\x00"
    total = 0
    for index in range(0, len(data), 2):
        total += (data[index] << 8) | data[index + 1]
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return (~total) & 0xFFFF


def _parse_igmp_outer(raw, ethertype_offset):
    """解析 IPv4 帧外层并定位未分片的 IGMP 报文。

    - 返回 None：非 IPv4/IGMP、IPv4 头非法或校验失败、任何分片，调用方按
      普通 IPv4 帧处理（组播沿用泛洪或成员投递）；
    - 返回 ("invalid",)：IPv4 外层合法且为未分片协议号 2，但 IPv4 总长度
      容纳不了最短 IGMP 报文或超过实际载荷，调用方固定输出 igmp_invalid；
    - 返回 ("ok", igmp_msg)：校验通过的外层，igmp_msg 为按 IPv4 总长度截
      取的完整 IGMP 报文（调用方按类型继续校验）。
    """
    payload = raw[ethertype_offset + 2:-4]
    if len(payload) < 20:
        return None
    version_ihl = payload[0]
    if version_ihl >> 4 != 4:
        return None
    ihl = version_ihl & 0x0F
    if ihl < 5:
        return None
    header_len = ihl * 4
    if len(payload) < header_len:
        return None
    if _internet_checksum(payload[:header_len]) != 0:  # IPv4 头校验
        return None
    fragment_word = (payload[6] << 8) | payload[7]
    # MF（bit13）或片偏移（bit0..12）非零：任何分片都不识别；DF 忽略
    if fragment_word & 0x3FFF:
        return None
    if payload[9] != IP_PROTOCOL_IGMP:
        return None
    total_length = (payload[2] << 8) | payload[3]
    # IGMPv2 报文最短 8 字节；容纳不了或超过实际载荷均为非法
    if total_length < header_len + 8 or total_length > len(payload):
        return ("invalid",)
    return ("ok", payload[header_len:total_length])


def _igmp_v2_from_msg(igmp_msg):
    """对已截取的 IGMP 报文做 IGMPv2 Query/Report/Leave 校验。"""
    mtype = igmp_msg[0]
    if mtype not in IGMP_CONTROL_ACTIONS:
        return ("invalid",)  # 类型非法（含 IGMPv3 等）
    if len(igmp_msg) != 8:
        return ("invalid",)  # IGMPv2 Query/Report/Leave 恰为 8 字节
    if _internet_checksum(igmp_msg) != 0:  # IGMP 校验
        return ("invalid",)
    octets = igmp_msg[4:8]
    group = ".".join(str(value) for value in octets)
    if mtype in (IGMP_TYPE_REPORT_V2, IGMP_TYPE_LEAVE_V2):
        if not 224 <= octets[0] <= 239:  # Report/Leave 组地址须为 D 类
            return ("invalid",)
    else:
        # Query：通用查询组地址 0.0.0.0 合法，组特定查询须为 D 类，
        # 其余组地址非法
        if tuple(octets) != (0, 0, 0, 0) and not 224 <= octets[0] <= 239:
            return ("invalid",)
    return ("ok", mtype, group)


def _ipv4_unicast(octets):
    """有效单播地址：首字节 1..223（A/B/C 类），排除 127 环回段；
    0.x 为本网、224+ 为组播/保留/广播。"""
    return 1 <= octets[0] <= 223 and octets[0] != 127


def _parse_igmp_v3_report(igmp_msg):
    """校验并解析 IGMPv3 Membership Report（类型 0x22）。

    返回 ("invalid",) 或 ("v3", records)；records 为
    (rtype, group, [source, ...]) 列表，group/source 为点分十进制。
    校验：整报校验和为 0、恰 8 字节定长头、组记录数与内容一致且长度闭合、
    记录类型在 1 至 6、组地址为 D 类、源地址为有效单播。
    """
    if len(igmp_msg) < 8 or igmp_msg[0] != IGMP_TYPE_REPORT_V3:
        return ("invalid",)
    if _internet_checksum(igmp_msg) != 0:  # IGMP 校验
        return ("invalid",)
    record_count = (igmp_msg[6] << 8) | igmp_msg[7]
    offset = 8
    records = []
    for _ in range(record_count):
        if len(igmp_msg) - offset < 8:  # 记录定长头 8 字节
            return ("invalid",)
        rtype = igmp_msg[offset]
        aux_len = igmp_msg[offset + 1]
        source_count = (
            (igmp_msg[offset + 2] << 8) | igmp_msg[offset + 3]
        )
        group_octets = igmp_msg[offset + 4:offset + 8]
        if rtype not in IGMPV3_RECORD_TYPES:
            return ("invalid",)
        if not 224 <= group_octets[0] <= 239:  # 组地址须为 D 类
            return ("invalid",)
        body_end = offset + 8 + 4 * source_count
        record_end = body_end + 4 * aux_len
        if record_end > len(igmp_msg):  # 源数组或辅助数据长度不闭合
            return ("invalid",)
        sources = []
        for source_index in range(source_count):
            start = offset + 8 + 4 * source_index
            source_octets = igmp_msg[start:start + 4]
            if not _ipv4_unicast(source_octets):  # 源地址须为有效单播
                return ("invalid",)
            sources.append(
                ".".join(str(value) for value in source_octets)
            )
        records.append(
            (
                rtype,
                ".".join(str(value) for value in group_octets),
                sources,
            )
        )
        offset = record_end
    if offset != len(igmp_msg):  # 记录数与内容不符（有剩余字节）
        return ("invalid",)
    return ("v3", records)


def _parse_igmp(raw, ethertype_offset):
    """IGMP 统一解析：在外层校验基础上区分 IGMPv2 三类与 IGMPv3 Report。

    返回 None（不识别为 IGMP）、("invalid",)（外层合法但 IGMP 非法）、
    ("ok", mtype, group)（IGMPv2）或 ("v3", records)（IGMPv3 Report）。
    """
    outer = _parse_igmp_outer(raw, ethertype_offset)
    if outer is None:
        return None
    if outer[0] == "invalid":
        return ("invalid",)
    igmp_msg = outer[1]
    if igmp_msg[0] == IGMP_TYPE_REPORT_V3:
        return _parse_igmp_v3_report(igmp_msg)
    return _igmp_v2_from_msg(igmp_msg)


def _ipv4_multicast_data(raw, ethertype_offset):
    """IPv4 组播数据帧：目的组地址为 D 类且与目的 MAC 映射一致时返回
    (source, group) 点分十进制（source 原样读取，是否投递交成员过滤条件
    判定），否则返回 None（调用方沿用泛洪）。"""
    payload = raw[ethertype_offset + 2:-4]
    if len(payload) < 20:
        return None
    source_octets = payload[12:16]
    group_octets = payload[16:20]
    if not 224 <= group_octets[0] <= 239:
        return None
    expected_mac = IPV4_MC_MAC_PREFIX + bytes(
        (group_octets[1] & 0x7F, group_octets[2], group_octets[3])
    )
    if raw[0:6] != expected_mac:
        return None
    return (
        ".".join(str(value) for value in source_octets),
        ".".join(str(value) for value in group_octets),
    )


def _forward_stp_work_total(bridges, links, ports, events):
    """forward-stp 工作量公式总值（不含上限比较），供 forward-stp 系与
    igmp-snoop-decode 复用。B、L、P 为桥、链路、端口数，U 为 up 链路数，
    E 为此前帧数：初始收敛 B+L+2U；帧计 E+P+1；链路计
    E*(P+1)+B+L+2U+2P+1（幂等也计，U 先应用）。
    """
    B = len(bridges)
    L = len(links)
    P = len(ports)
    sim_up = {link["id"]: link["up"] for link in links}
    U = sum(1 for link in links if link["up"])
    E = 0
    work = B + L + 2 * U  # 初始收敛
    for item in events:
        if item[0] == "link":
            _, _, lid, up = item
            if sim_up[lid] != up:
                sim_up[lid] = up
                U += 1 if up else -1
            work += E * (P + 1) + B + L + 2 * U + 2 * P + 1
        else:
            work += E + P + 1
            E += 1
    return work


def forward_stp_work(bridges, links, ports, events, limit):
    """forward-stp 的工作量预演：仅跟踪 up 链路数与帧数，无副作用。

    累计等于上限合法，首次超过即抛 ForwardStpWorkLimit。
    """
    if _forward_stp_work_total(bridges, links, ports, events) > limit:
        raise ForwardStpWorkLimit


def _igmp_v3_work_units(events):
    """统计帧序列中合法 IGMPv3 Report 的组记录数与源地址数之和。

    仅依据原始帧外层与报文解析（与帧分类、VLAN 准入、STP 状态无关，预演
    无副作用）：每个完整解析成功的 v3 组记录计 1，其每个源地址再计 1。
    """
    units = 0
    for item in events:
        if item[0] != "frame":
            continue
        raw = item[3]
        ethertype_offset = 16 if raw[12:14] == FRAME_DECODE_TAG else 12
        ethertype = (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        )
        if ethertype != IPV4_ETHER_TYPE:
            continue
        igmp_info = _parse_igmp(raw, ethertype_offset)
        if igmp_info is not None and igmp_info[0] == "v3":
            records = igmp_info[1]
            units += len(records) + sum(
                len(sources) for _, _, sources in records
            )
    return units


def igmp_snoop_work(bridges, links, ports, events, limit):
    """igmp-snoop-decode 工作量预演：现有 stp-decode（forward-stp）工作量
    再加 N*(N+P+1)，N 为事件数（链路与帧合计）、P 为端口数；IGMPv3
    Report 每个组记录及每个源地址各再加一个单位。等于上限合法，超过即
    抛 IgmpWorkLimit。
    """
    N = len(events)
    P = len(ports)
    work = _forward_stp_work_total(bridges, links, ports, events)
    work += N * (N + P + 1)
    work += _igmp_v3_work_units(events)
    if work > limit:
        raise IgmpWorkLimit


def igmp_snoop_decode(
    bridges, links, delay, bridge_name, ports, age, max_frame,
    membership_age, router_ports, events, observer=None,
):
    """在 stp-decode 转发/学习/统计语义上增加 IGMPv2/v3 snooping。

    成员表 membership：(vlan, group) -> {port: member}。IGMPv2 成员为
    expires（绝对时刻）整数，键形保持 name/expires；经 IGMPv3 Report 更新
    的成员为 {"expires": expires, "mode": "include"/"exclude",
    "sources": set(点分十进制源地址)}。
    每个事件前删除 expires<=t 的成员；IGMPv2 Report 建立或刷新至
    t+membership_age，Leave 立即删除入端口成员；IGMPv3 Report 按组记录
    顺序在暂存表上修改过滤状态，整帧校验成功后一次提交，受影响成员
    expires 统一为 t+membership_age；链路断开或端口退出 forwarding 时清除
    该端口全部成员。Report/Leave 仅发往同 VLAN 可转发的 router_ports，无
    合格路由端口时泛洪；Query 始终泛洪；其他 IPv4 组播在 MAC/组地址映射
    一致且有成员匹配源过滤条件时仅发往匹配成员与路由端口；其余组播沿用
    泛洪。协议号 2 但 IGMP 非法的帧固定 igmp_invalid、空 ports、计 drop
    且不改任何状态。observer 语义同 stp-check。
    """
    by_id = {link["id"]: link for link in links}
    by_name = {port["name"]: port for port in ports}
    port_link = {}  # 本桥桥链路口名 -> link
    for link in links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [port, seen]
    # (vlan, group) -> {port_name: int 过期时刻或 v3 过滤 dict}
    membership = {}
    router_set = set(router_ports)
    port_stats = {
        port["name"]: {
            "rx": 0,
            "tx": 0,
            "drop": 0,
            "good": 0,
            "runt": 0,
            "giant": 0,
            "alignment": 0,
            "bad_fcs": 0,
        }
        for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    results = []
    if observer is not None:  # record/replay：逐事件记录 applied 与输出
        observer["items"] = []

    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    roles = {name: {} for name in bridges}

    def converge(t):
        _, _, new_roles = stp_converge(bridges, links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        """返回 (物理 up, STP 状态)；边缘口恒为 up 即 forwarding。"""
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"  # alternate
        return True, state

    def eligible_names(t, vlan, ingress):
        """同 VLAN 可转发（物理 up、STP forwarding、VLAN 准入）且排除入
        端口的端口名，按配置端口序。"""
        return [
            port["name"]
            for port in ports
            if vlan in port["allowed"]
            and port["name"] != ingress
            and port_status(port["name"], t) == (True, "forwarding")
        ]

    def member_expires(entry):
        """v2 成员为过期时刻整数；v3 成员为含 expires 的过滤 dict。"""
        return entry if isinstance(entry, int) else entry["expires"]

    def apply_v3_record(table, port_name, rtype, sources, expiry):
        """按单条 v3 组记录修改入端口在本组的暂存过滤状态。

        无记录或 v2 成员按 EXCLUDE、空源集合处理；INCLUDE 空集合删除
        成员，EXCLUDE 空集合表示接收全部源。
        """
        sources = set(sources)
        current = table.get(port_name)
        if isinstance(current, dict):
            mode, current_sources = current["mode"], set(current["sources"])
        elif isinstance(current, int):
            # IGMPv2 成员接收全部源，按 EXCLUDE、空集合处理
            mode, current_sources = "exclude", set()
        else:
            # 无既有成员等价于 INCLUDE、空集合：ALLOW 建立成员，
            # BLOCK 仍为空集合删除
            mode, current_sources = "include", set()
        if rtype in (IGMPV3_MODE_IS_INCLUDE, IGMPV3_CHANGE_TO_INCLUDE):
            new_mode, new_sources = "include", sources
        elif rtype in (IGMPV3_MODE_IS_EXCLUDE, IGMPV3_CHANGE_TO_EXCLUDE):
            new_mode, new_sources = "exclude", sources
        elif rtype == IGMPV3_ALLOW_NEW_SOURCES:
            if mode == "include":  # INCLUDE 取并集
                new_mode, new_sources = "include", current_sources | sources
            else:  # EXCLUDE 做差集
                new_mode, new_sources = "exclude", current_sources - sources
        else:  # BLOCK_OLD_SOURCES：INCLUDE 做差集，EXCLUDE 取并集
            if mode == "include":
                new_mode, new_sources = "include", current_sources - sources
            else:
                new_mode, new_sources = "exclude", current_sources | sources
        if new_mode == "include" and not new_sources:
            table.pop(port_name, None)  # INCLUDE 空集合：删除成员
        else:
            table[port_name] = {
                "expires": expiry,
                "mode": new_mode,
                "sources": new_sources,
            }

    def member_matches(entry, source):
        """组播数据源过滤：v2 成员接收全部源；v3 成员按 INCLUDE/EXCLUDE。"""
        if not isinstance(entry, dict):
            return True
        if entry["mode"] == "include":
            return source in entry["sources"]
        return source not in entry["sources"]

    def purge_expired(t):
        for key, table in [
            (key, table) for key, table in membership.items()
        ]:
            for port_name in [
                name
                for name, entry in table.items()
                if member_expires(entry) <= t
            ]:
                del table[port_name]
            if not table:
                del membership[key]

    converge(0)
    for item in events:
        t = item[1]
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        purge_expired(t)  # 每个事件前删除 expires<=t 的成员
        if item[0] == "link":
            _, t, lid, up = item
            applied = by_id[lid]["up"] != up  # up 实际改变才 applied
            old_forwarding = forwarding_ports(t)
            by_id[lid]["up"] = up
            converge(t)
            left_forwarding = old_forwarding - forwarding_ports(t)
            for name in left_forwarding:
                # 端口退出 forwarding：清 FDB（同 stp-decode）与该端口全部
                # 组成员（链路断开同理，断口必退出 forwarding）
                for key in [k for k, (p, _) in fdb.items() if p == name]:
                    del fdb[key]
                for key, table in [
                    (key, table) for key, table in membership.items()
                ]:
                    if name in table:
                        del table[name]
                        if not table:
                            del membership[key]
            if observer is not None:  # 链路项：output 恒 None
                observer["items"].append(
                    {"kind": "link", "t": t, "applied": applied,
                     "output": None}
                )
            continue
        _, t, port_name, raw = item
        dst = _format_mac(raw[0:6])
        src = _format_mac(raw[6:12])
        if raw[12:14] == FRAME_DECODE_TAG:
            tci = (raw[14] << 8) | raw[15]
            tag = tci & 0x0FFF
            ethertype_offset = 16
        else:
            tag = None
            ethertype_offset = 12
        ethertype = (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        )
        length = len(raw)
        port_stats[port_name]["rx"] += 1
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif raw[-4:] != (
            zlib.crc32(raw[:-4]) & 0xFFFFFFFF
        ).to_bytes(4, "little"):
            cls = "bad_fcs"
        else:
            cls = "good"
        port_stats[port_name][cls] += 1
        if cls != "good":  # 非 good 丢弃且不学习、不转发、不计 VLAN
            port_stats[port_name]["drop"] += 1
            entry = {"t": t, "class": cls, "action": "drop", "ports": []}
            results.append(entry)
            if observer is not None:
                observer["items"].append(
                    {"kind": "frame", "t": t, "applied": True,
                     "output": entry}
                )
            continue
        if tag is None:
            vlan = by_name[port_name]["pvid"]
            rejected = False
        else:
            vlan = tag
            ingress = by_name[port_name]
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # VLAN 准入拒绝：不学习、不计 VLAN
            port_stats[port_name]["drop"] += 1
            entry = {"t": t, "class": cls, "action": "drop", "ports": []}
            results.append(entry)
            if observer is not None:  # 准入拒绝也逐帧记录
                observer["items"].append(
                    {"kind": "frame", "t": t, "applied": True,
                     "output": entry}
                )
            continue
        vlan_stats[vlan]["rx"] += 1
        _, state = port_status(port_name, t)
        egress = []
        action = "drop"
        if state == "learning":
            fdb[(vlan, src)] = [port_name, t]
        elif state == "forwarding":
            igmp_info = (
                _parse_igmp(raw, ethertype_offset)
                if ethertype == IPV4_ETHER_TYPE
                else None
            )
            if igmp_info is not None and igmp_info[0] == "invalid":
                # 外层合法的协议号 2 帧但 IGMP 非法：不改任何状态，
                # action 固定 igmp_invalid、ports 为空并计入丢弃
                port_stats[port_name]["drop"] += 1
                vlan_stats[vlan]["drop"] += 1
                entry = {
                    "t": t, "class": cls, "action": "igmp_invalid",
                    "ports": [],
                }
                results.append(entry)
                if observer is not None:
                    observer["items"].append(
                        {"kind": "frame", "t": t, "applied": True,
                         "output": entry}
                    )
                continue
            fdb[(vlan, src)] = [port_name, t]
            is_group = int(dst[:2], 16) & 1
            eligible = eligible_names(t, vlan, port_name)
            if igmp_info is not None and igmp_info[0] == "v3":
                # IGMPv3 Membership Report：解析已对整帧校验成功，此处一次
                # 提交；组记录按报文顺序作用，受影响成员 expires 统一为
                # t+membership_age
                _, records = igmp_info
                expiry = t + membership_age
                for rtype, group, sources in records:
                    table = membership.setdefault((vlan, group), {})
                    apply_v3_record(
                        table, port_name, rtype, sources, expiry
                    )
                    if not table:
                        del membership[(vlan, group)]
                routers = [
                    name for name in eligible if name in router_set
                ]
                egress = routers if routers else eligible
                action = "igmpv3_report"
            elif igmp_info is not None:  # 合法 IGMPv2 控制帧
                _, mtype, group = igmp_info
                if mtype == IGMP_TYPE_REPORT_V2:
                    membership.setdefault((vlan, group), {})[port_name] = (
                        t + membership_age
                    )
                    routers = [
                        name for name in eligible if name in router_set
                    ]
                    egress = routers if routers else eligible
                    action = "igmp_report"
                elif mtype == IGMP_TYPE_LEAVE_V2:
                    table = membership.get((vlan, group))
                    if table is not None:  # Leave 立即删除入端口成员
                        table.pop(port_name, None)
                        if not table:
                            del membership[(vlan, group)]
                    routers = [
                        name for name in eligible if name in router_set
                    ]
                    egress = routers if routers else eligible
                    action = "igmp_leave"
                else:  # Query：始终泛洪，不改成员状态
                    egress = eligible
                    action = "igmp_query"
            elif is_group:
                multicast = (
                    _ipv4_multicast_data(raw, ethertype_offset)
                    if ethertype == IPV4_ETHER_TYPE
                    else None
                )
                group = multicast[1] if multicast is not None else None
                table = (
                    membership.get((vlan, group))
                    if group is not None
                    else None
                )
                if table:  # 命中成员表：匹配源过滤的成员加路由端口
                    source = multicast[0]
                    matching = {
                        name
                        for name, entry in table.items()
                        if member_matches(entry, source)
                    }
                    targets = matching | router_set
                    egress = [
                        name for name in eligible if name in targets
                    ]
                    action = "multicast"
                else:  # 其余组播（含广播、非 IPv4、映射不一致、无成员）泛洪

                    egress = eligible
                    action = "flood"
            else:
                hit = fdb.get((vlan, dst))
                if hit is not None and hit[0] != port_name:
                    target = hit[0]
                    target_up, target_state = port_status(target, t)
                    if (
                        target_up
                        and target_state == "forwarding"
                        and vlan in by_name[target]["allowed"]
                    ):
                        egress = [target]
                        action = "unicast"
                elif hit is None:
                    egress = eligible
                    action = "flood"
        out_ports = []
        for name in egress:
            port_stats[name]["tx"] += 1
            vlan_stats[vlan]["tx"] += 1
            out_ports.append(
                {
                    "name": name,
                    "vlan": None if vlan in by_name[name]["untagged"] else vlan,
                }
            )
        if not egress:
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        entry = {"t": t, "class": cls, "action": action, "ports": out_ports}
        results.append(entry)
        if observer is not None:  # 帧项恒 applied，output 为对应结果项
            observer["items"].append(
                {"kind": "frame", "t": t, "applied": True, "output": entry}
            )
    port_order = {port["name"]: index for index, port in enumerate(ports)}
    groups = []
    for vlan, group in sorted(
        membership,
        key=lambda key: (
            key[0], tuple(int(part) for part in key[1].split("."))
        ),
    ):
        table = membership[(vlan, group)]
        members = []
        # 成员按配置端口序；v2 成员保持 name/expires 键形，v3 成员按固定
        # 键序 name/expires/mode/sources，源地址数值升序
        for name in sorted(table, key=lambda value: port_order[value]):
            entry = table[name]
            if isinstance(entry, dict):
                sources = sorted(
                    entry["sources"],
                    key=lambda value: tuple(
                        int(part) for part in value.split(".")
                    ),
                )
                members.append(
                    {
                        "name": name,
                        "expires": entry["expires"],
                        "mode": entry["mode"],
                        "sources": sources,
                    }
                )
            else:
                members.append({"name": name, "expires": entry})
        groups.append({"vlan": vlan, "group": group, "members": members})
    return {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
                "good": port_stats[port["name"]]["good"],
                "runt": port_stats[port["name"]]["runt"],
                "giant": port_stats[port["name"]]["giant"],
                "alignment": port_stats[port["name"]]["alignment"],
                "bad_fcs": port_stats[port["name"]]["bad_fcs"],
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
        "groups": groups,
    }


# mld-snoop-decode：与 igmp-snoop-decode 同构，在 stp-decode（stp-check
# 七键）配置上追加 mld 对象，处理 IPv6 上的 MLDv1 Query/Report/Done 与
# MLDv2 Membership Report
MLD_SNOOP_CONFIG_KEYS = STP_CHECK_CONFIG_KEYS | frozenset(("mld",))
MLD_KEYS = frozenset(("membership_age", "router_ports"))
IPV6_ETHER_TYPE = 0x86DD
IP_PROTOCOL_HOPOPT = 0
IP_PROTOCOL_ICMPV6 = 58
IPV6_ROUTER_ALERT_OPTION = 5
IPV6_ROUTER_ALERT_MLD = b"\x00\x00"
MLD_TYPE_QUERY_V1 = 130
MLD_TYPE_REPORT_V1 = 131
MLD_TYPE_DONE_V1 = 132
MLD_TYPE_REPORT_V2 = 143
MLD_CONTROL_ACTIONS = {
    MLD_TYPE_QUERY_V1: "mld_query",
    MLD_TYPE_REPORT_V1: "mld_report",
    MLD_TYPE_DONE_V1: "mld_done",
}
# MLDv2 Membership Report 组记录类型
MLDV2_MODE_IS_INCLUDE = 1
MLDV2_MODE_IS_EXCLUDE = 2
MLDV2_CHANGE_TO_INCLUDE = 3
MLDV2_CHANGE_TO_EXCLUDE = 4
MLDV2_ALLOW_NEW_SOURCES = 5
MLDV2_BLOCK_OLD_SOURCES = 6
MLDV2_RECORD_TYPES = frozenset(range(1, 7))
IPV6_MC_MAC_PREFIX = b"\x33\x33"


def validate_mld_snoop_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != MLD_SNOOP_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # 七键与 stp-decode（stp-check）完全一致，复用其全量校验
    bridges, links, delay, bridge, ports, age, max_frame = (
        validate_stp_check_config(
            {key: config[key] for key in STP_CHECK_CONFIG_KEYS}
        )
    )
    mld = config["mld"]
    if not isinstance(mld, dict) or frozenset(mld) != MLD_KEYS:
        raise InvalidInput("bad mld")
    membership_age = mld["membership_age"]
    if not _is_int(membership_age) or membership_age <= 0:
        raise InvalidInput("bad mld membership_age")
    router_ports = mld["router_ports"]
    if not isinstance(router_ports, list):
        raise InvalidInput("bad mld router_ports")
    name_set = {port["name"] for port in ports}
    for name in router_ports:
        if not isinstance(name, str) or name not in name_set:
            raise InvalidInput("bad mld router port")
    if len(set(router_ports)) != len(router_ports):  # 端口名不重复
        raise InvalidInput("bad mld router_ports")
    return (
        bridges, links, delay, bridge, ports, age, max_frame,
        membership_age, tuple(router_ports),
    )


def _format_ipv6(octets):
    """确定的小写压缩 IPv6 形式。"""
    return str(ipaddress.IPv6Address(bytes(octets)))


def _ipv6_group_valid(octets):
    """MLD 组地址：ff00::/8。"""
    return octets[0] == 0xFF


def _ipv6_source_valid(octets):
    """MLDv2 记录源地址：非未指定 :: 且非组播 ff00::/8（链路本地等合法）。"""
    return octets[0] != 0xFF and any(octets)


def _icmpv6_checksum(src, dst, body):
    """ICMPv6 伪首部反码求和：src/dst 各 16 字节、上层长度 4 字节、
    下一首部 58（4 字节零填充）加报文本体；校验时整段求和须为 0。"""
    pseudo = (
        bytes(src) + bytes(dst)
        + len(body).to_bytes(4, "big")
        + b"\x00\x00\x00" + bytes([IP_PROTOCOL_ICMPV6])
    )
    data = pseudo + body
    if len(data) % 2:
        data = data + b"\x00"
    total = 0
    for index in range(0, len(data), 2):
        total += (data[index] << 8) | data[index + 1]
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return (~total) & 0xFFFF


def _router_alert_value(options):
    """从 Hop-by-Hop 选项区查找 Router Alert 选项值。

    选项区畸形（长度不闭合）或不含类型 5 选项返回 None；类型 5 长度须恰为
    2，值原样返回（调用方判定是否为 MLD 的 0x0000）。
    """
    index = 0
    while index < len(options):
        otype = options[index]
        if otype == 0:  # Pad1
            index += 1
            continue
        if index + 1 >= len(options):
            return None
        olen = options[index + 1]
        if index + 2 + olen > len(options):  # 选项长度不闭合
            return None
        if otype == IPV6_ROUTER_ALERT_OPTION:
            if olen != 2:
                return None
            return bytes(options[index + 2:index + 4])
        index += 2 + olen
    return None


def _parse_mld_outer(raw, ethertype_offset):
    """解析 IPv6 外层并定位携带 Router Alert 的 ICMPv6（MLD）报文。

    - 返回 None：非 IPv6、无 Hop-by-Hop Router Alert、封装的下一首部不是
      ICMPv6、或任何扩展头/分片（不重组，调用方按普通 IPv6 帧处理）；
    - 返回 ("invalid",)：已凭 Router Alert+ICMPv6 识别为 MLD 候选，但
      IPv6 外层边界、Hop Limit 或报文长度不合法，调用方固定输出 mld_invalid；
    - 返回 ("ok", src, dst, body)：外层校验通过，body 为按 Payload Length
      截取的完整 MLD 报文（调用方按类型继续校验）。
    """
    payload = raw[ethertype_offset + 2:-4]
    if len(payload) < 40:
        return None
    if payload[0] >> 4 != 6:
        return None
    next_header = payload[6]
    if next_header != IP_PROTOCOL_HOPOPT:
        # MLD 必须携带 Router Alert；其他下一首部（含分片）一律不识别
        return None
    if len(payload) < 48:
        return None
    ext_len = (payload[41] + 1) * 8
    if ext_len < 8 or 40 + ext_len > len(payload):
        return None  # 扩展头畸形：不识别，按普通 IPv6 帧处理
    ra = _router_alert_value(payload[42:40 + ext_len])
    if ra is None or ra != IPV6_ROUTER_ALERT_MLD:
        # 无 Router Alert 或值非 MLD(0)：不识别为 MLD
        return None
    next_header = payload[40]
    if next_header != IP_PROTOCOL_ICMPV6:
        return None
    # 已识别为 MLD 候选：以下外层语义失败固定 mld_invalid
    payload_length = int.from_bytes(payload[4:6], "big")
    if payload_length > len(payload) - 40:  # IPv6 外层边界不闭合
        return ("invalid",)
    if payload[7] != 1:  # Hop Limit 须为 1
        return ("invalid",)
    body_end = 40 + payload_length
    if 40 + ext_len > body_end:  # 扩展头越出声明载荷
        return ("invalid",)
    body = payload[40 + ext_len:body_end]
    if len(body) < 8:  # MLD 报文最短为 24 字节，8 字节尚容纳不了
        return ("invalid",)
    return ("ok", bytes(payload[8:24]), bytes(payload[24:40]), body)


def _mld_v1_from_msg(src, dst, body):
    """对已截取的 MLD 报文做 MLDv1 Query/Report/Done 校验。

    三类报文恰为 24 字节、Code 须为 0、伪首部校验和为 0；外层源地址须非
    ::/非组播，外层目的须为组播。Query 组地址允许 ::（通用查询）或
    ff00::/8，Report/Done 组地址须为 ff00::/8。
    """
    mtype = body[0]
    if mtype not in MLD_CONTROL_ACTIONS:
        return ("invalid",)  # 类型非法（含 MLDv2 Report 等）
    if len(body) != 24 or body[1] != 0:
        return ("invalid",)
    if not _ipv6_source_valid(src) or not _ipv6_group_valid(dst):
        return ("invalid",)
    if _icmpv6_checksum(src, dst, body) != 0:
        return ("invalid",)
    group = bytes(body[8:24])
    if mtype in (MLD_TYPE_REPORT_V1, MLD_TYPE_DONE_V1):
        if not _ipv6_group_valid(group):
            return ("invalid",)
    elif not (_ipv6_group_valid(group) or not any(group)):
        # Query：通用查询组地址 :: 合法，组特定查询须为 ff00::/8
        return ("invalid",)
    return ("ok", mtype, group)


def _parse_mld_v2_report(src, dst, body):
    """校验并解析 MLDv2 Membership Report（类型 143）。

    返回 ("invalid",) 或 ("v2", records)；records 为
    (rtype, group_bytes, [source_bytes, ...]) 列表。
    校验：类型 143、恰 8 字节定长头、整报伪首部校验和为 0、组记录数与
    内容一致且长度闭合、记录类型在 1 至 6、组地址为 ff00::/8、源地址非
    ::/非组播、外层源非 ::/非组播且外层目的为组播。
    """
    if len(body) < 8 or body[0] != MLD_TYPE_REPORT_V2:
        return ("invalid",)
    if not _ipv6_source_valid(src) or not _ipv6_group_valid(dst):
        return ("invalid",)
    if _icmpv6_checksum(src, dst, body) != 0:
        return ("invalid",)
    record_count = int.from_bytes(body[6:8], "big")
    offset = 8
    records = []
    for _ in range(record_count):
        if len(body) - offset < 20:  # 记录定长头 20 字节
            return ("invalid",)
        rtype = body[offset]
        aux_len = body[offset + 1]
        source_count = int.from_bytes(body[offset + 2:offset + 4], "big")
        group = bytes(body[offset + 4:offset + 20])
        if rtype not in MLDV2_RECORD_TYPES:
            return ("invalid",)
        if not _ipv6_group_valid(group):  # 组地址须为 ff00::/8
            return ("invalid",)
        body_end = offset + 20 + 16 * source_count
        record_end = body_end + 4 * aux_len
        if record_end > len(body):  # 源数组或辅助数据长度不闭合
            return ("invalid",)
        sources = []
        for source_index in range(source_count):
            start = offset + 20 + 16 * source_index
            source = bytes(body[start:start + 16])
            if not _ipv6_source_valid(source):  # 源地址须合法
                return ("invalid",)
            sources.append(source)
        records.append((rtype, group, sources))
        offset = record_end
    if offset != len(body):  # 记录数与内容不符（有剩余字节）
        return ("invalid",)
    return ("v2", records)


def _parse_mld(raw, ethertype_offset):
    """MLD 统一解析：在外层校验基础上区分 MLDv1 三类与 MLDv2 Report。

    返回 None（不识别为 MLD）、("invalid",)（外层识别但 MLD 非法）、
    ("ok", mtype, group_bytes)（MLDv1）或 ("v2", records)（MLDv2 Report）。
    """
    outer = _parse_mld_outer(raw, ethertype_offset)
    if outer is None:
        return None
    if outer[0] == "invalid":
        return ("invalid",)
    _, src, dst, body = outer
    if body[0] == MLD_TYPE_REPORT_V2:
        return _parse_mld_v2_report(src, dst, body)
    return _mld_v1_from_msg(src, dst, body)


def _ipv6_multicast_data(raw, ethertype_offset):
    """IPv6 组播数据帧：目的地址为 ff00::/8 且与目的 MAC 的 33:33 映射
    一致时返回 (src_bytes, dst_bytes)，否则返回 None（调用方沿用泛洪）。"""
    payload = raw[ethertype_offset + 2:-4]
    if len(payload) < 40:
        return None
    dst = bytes(payload[24:40])
    if not _ipv6_group_valid(dst):
        return None
    if raw[0:6] != IPV6_MC_MAC_PREFIX + dst[12:16]:
        return None
    return bytes(payload[8:24]), dst


def _mld_v2_work_units(events):
    """统计帧序列中合法 MLDv2 Report 的组记录数与源地址数之和。

    仅依据原始帧外层与报文解析（与帧分类、VLAN 准入、STP 状态无关，预演
    无副作用）：每个完整解析成功的 v2 组记录计 1，其每个源地址再计 1。
    """
    units = 0
    for item in events:
        if item[0] != "frame":
            continue
        raw = item[3]
        ethertype_offset = 16 if raw[12:14] == FRAME_DECODE_TAG else 12
        ethertype = (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        )
        if ethertype != IPV6_ETHER_TYPE:
            continue
        mld_info = _parse_mld(raw, ethertype_offset)
        if mld_info is not None and mld_info[0] == "v2":
            records = mld_info[1]
            units += len(records) + sum(
                len(sources) for _, _, sources in records
            )
    return units


def mld_snoop_work(bridges, links, ports, events, limit):
    """mld-snoop-decode 工作量预演：现有 stp-decode（forward-stp）工作量
    再加 N*(N+P+1)，N 为事件数（链路与帧合计）、P 为端口数；MLDv2
    Report 每个组记录及每个源地址各再加一个单位。等于上限合法，超过即
    抛 MldWorkLimit。
    """
    N = len(events)
    P = len(ports)
    work = _forward_stp_work_total(bridges, links, ports, events)
    work += N * (N + P + 1)
    work += _mld_v2_work_units(events)
    if work > limit:
        raise MldWorkLimit


def mld_snoop_decode(
    bridges, links, delay, bridge_name, ports, age, max_frame,
    membership_age, router_ports, events, observer=None,
):
    """在 stp-decode 转发/学习/统计语义上增加 MLDv1/v2 snooping。

    成员表 membership：(vlan, group_bytes) -> {port: member}。MLDv1 成员为
    expires（绝对时刻）整数，键形保持 name/expires；经 MLDv2 Report 更新
    的成员为 {"expires": expires, "mode": "include"/"exclude",
    "sources": set(16 字节源地址)}。
    每个事件前删除 expires<=t 的成员；MLDv1 Report 建立或刷新至
    t+membership_age，Done 立即删除入端口成员；MLDv2 Report 按组记录
    顺序在暂存表上修改过滤状态，整帧校验成功后一次提交，受影响成员
    expires 统一为 t+membership_age；链路断开或端口退出 forwarding 时清除
    该端口全部成员。Report/Done 仅发往同 VLAN 可转发的 router_ports，无
    合格路由端口时泛洪；Query 始终泛洪；其他 IPv6 组播在 MAC/组地址
    33:33 映射一致且有成员匹配源过滤条件时仅发往匹配成员与路由端口；
    其余组播沿用泛洪。携带 Router Alert 的 ICMPv6 但 MLD 非法的帧固定
    mld_invalid、空 ports、计 drop 且不改任何状态（含不学习 MAC）。
    observer 语义同 stp-check。
    """
    by_id = {link["id"]: link for link in links}
    by_name = {port["name"]: port for port in ports}
    port_link = {}  # 本桥桥链路口名 -> link
    for link in links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [port, seen]
    # (vlan, group_bytes) -> {port_name: int 过期时刻或 v2 过滤 dict}
    membership = {}
    router_set = set(router_ports)
    port_stats = {
        port["name"]: {
            "rx": 0,
            "tx": 0,
            "drop": 0,
            "good": 0,
            "runt": 0,
            "giant": 0,

            "alignment": 0,
            "bad_fcs": 0,
        }
        for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    results = []
    if observer is not None:  # record/replay：逐事件记录 applied 与输出
        observer["items"] = []

    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    roles = {name: {} for name in bridges}

    def converge(t):
        _, _, new_roles = stp_converge(bridges, links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        """返回 (物理 up, STP 状态)；边缘口恒为 up 即 forwarding。"""
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"  # alternate
        return True, state

    def eligible_names(t, vlan, ingress):
        """同 VLAN 可转发（物理 up、STP forwarding、VLAN 准入）且排除入
        端口的端口名，按配置端口序。"""
        return [
            port["name"]
            for port in ports
            if vlan in port["allowed"]
            and port["name"] != ingress
            and port_status(port["name"], t) == (True, "forwarding")
        ]

    def member_expires(entry):
        """v1 成员为过期时刻整数；v2 成员为含 expires 的过滤 dict。"""
        return entry if isinstance(entry, int) else entry["expires"]

    def apply_v2_record(table, port_name, rtype, sources, expiry):
        """按单条 v2 组记录修改入端口在本组的暂存过滤状态。

        无记录或 v1 成员按 EXCLUDE、空源集合处理；INCLUDE 空集合删除
        成员，EXCLUDE 空集合表示接收全部源。
        """
        sources = set(sources)
        current = table.get(port_name)
        if isinstance(current, dict):
            mode, current_sources = current["mode"], set(current["sources"])
        elif isinstance(current, int):
            # MLDv1 成员接收全部源，按 EXCLUDE、空集合处理
            mode, current_sources = "exclude", set()
        else:
            # 无既有成员等价于 INCLUDE、空集合：ALLOW 建立成员，
            # BLOCK 仍为空集合删除
            mode, current_sources = "include", set()
        if rtype in (MLDV2_MODE_IS_INCLUDE, MLDV2_CHANGE_TO_INCLUDE):
            new_mode, new_sources = "include", sources
        elif rtype in (MLDV2_MODE_IS_EXCLUDE, MLDV2_CHANGE_TO_EXCLUDE):
            new_mode, new_sources = "exclude", sources
        elif rtype == MLDV2_ALLOW_NEW_SOURCES:
            if mode == "include":  # INCLUDE 取并集
                new_mode, new_sources = "include", current_sources | sources
            else:  # EXCLUDE 做差集
                new_mode, new_sources = "exclude", current_sources - sources
        else:  # BLOCK_OLD_SOURCES：INCLUDE 做差集，EXCLUDE 取并集
            if mode == "include":
                new_mode, new_sources = "include", current_sources - sources
            else:
                new_mode, new_sources = "exclude", current_sources | sources
        if new_mode == "include" and not new_sources:
            table.pop(port_name, None)  # INCLUDE 空集合：删除成员
        else:
            table[port_name] = {
                "expires": expiry,
                "mode": new_mode,
                "sources": new_sources,
            }

    def member_matches(entry, source):
        """组播数据源过滤：v1 成员接收全部源；v2 成员按 INCLUDE/EXCLUDE。"""
        if not isinstance(entry, dict):
            return True
        if entry["mode"] == "include":
            return source in entry["sources"]
        return source not in entry["sources"]

    def purge_expired(t):
        for key, table in [
            (key, table) for key, table in membership.items()
        ]:
            for port_name in [
                name
                for name, entry in table.items()
                if member_expires(entry) <= t
            ]:
                del table[port_name]
            if not table:
                del membership[key]

    converge(0)
    for item in events:
        t = item[1]
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        purge_expired(t)  # 每个事件前删除 expires<=t 的成员
        if item[0] == "link":
            _, t, lid, up = item
            applied = by_id[lid]["up"] != up  # up 实际改变才 applied
            old_forwarding = forwarding_ports(t)
            by_id[lid]["up"] = up
            converge(t)
            left_forwarding = old_forwarding - forwarding_ports(t)
            for name in left_forwarding:
                # 端口退出 forwarding：清 FDB（同 stp-decode）与该端口全部
                # 组成员（链路断开同理，断口必退出 forwarding）
                for key in [k for k, (p, _) in fdb.items() if p == name]:
                    del fdb[key]
                for key, table in [
                    (key, table) for key, table in membership.items()
                ]:
                    if name in table:
                        del table[name]
                        if not table:
                            del membership[key]
            if observer is not None:  # 链路项：output 恒 None
                observer["items"].append(
                    {"kind": "link", "t": t, "applied": applied,
                     "output": None}
                )
            continue
        _, t, port_name, raw = item
        dst = _format_mac(raw[0:6])
        src = _format_mac(raw[6:12])
        if raw[12:14] == FRAME_DECODE_TAG:
            tci = (raw[14] << 8) | raw[15]
            tag = tci & 0x0FFF
            ethertype_offset = 16
        else:
            tag = None
            ethertype_offset = 12
        ethertype = (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        )
        length = len(raw)
        port_stats[port_name]["rx"] += 1
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif raw[-4:] != (
            zlib.crc32(raw[:-4]) & 0xFFFFFFFF
        ).to_bytes(4, "little"):
            cls = "bad_fcs"
        else:
            cls = "good"
        port_stats[port_name][cls] += 1
        if cls != "good":  # 非 good 丢弃且不学习、不转发、不计 VLAN
            port_stats[port_name]["drop"] += 1
            entry = {"t": t, "class": cls, "action": "drop", "ports": []}
            results.append(entry)
            if observer is not None:
                observer["items"].append(
                    {"kind": "frame", "t": t, "applied": True,
                     "output": entry}
                )
            continue
        if tag is None:
            vlan = by_name[port_name]["pvid"]
            rejected = False
        else:
            vlan = tag
            ingress = by_name[port_name]
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # VLAN 准入拒绝：不学习、不计 VLAN
            port_stats[port_name]["drop"] += 1
            entry = {"t": t, "class": cls, "action": "drop", "ports": []}
            results.append(entry)
            if observer is not None:  # 准入拒绝也逐帧记录
                observer["items"].append(
                    {"kind": "frame", "t": t, "applied": True,
                     "output": entry}
                )
            continue
        vlan_stats[vlan]["rx"] += 1
        _, state = port_status(port_name, t)
        egress = []
        action = "drop"
        if state == "learning":
            fdb[(vlan, src)] = [port_name, t]
        elif state == "forwarding":
            mld_info = (
                _parse_mld(raw, ethertype_offset)
                if ethertype == IPV6_ETHER_TYPE
                else None
            )
            if mld_info is not None and mld_info[0] == "invalid":
                # 携带 Router Alert 的 ICMPv6 帧但 MLD 非法：不改任何状态
                # （不学习 MAC、不改成员），action 固定 mld_invalid、
                # ports 为空并计入丢弃
                port_stats[port_name]["drop"] += 1
                vlan_stats[vlan]["drop"] += 1
                entry = {
                    "t": t, "class": cls, "action": "mld_invalid",
                    "ports": [],
                }
                results.append(entry)
                if observer is not None:
                    observer["items"].append(
                        {"kind": "frame", "t": t, "applied": True,
                         "output": entry}
                    )
                continue
            fdb[(vlan, src)] = [port_name, t]
            is_group = int(dst[:2], 16) & 1
            eligible = eligible_names(t, vlan, port_name)
            if mld_info is not None and mld_info[0] == "v2":
                # MLDv2 Membership Report：解析已对整帧校验成功，此处一次
                # 提交；组记录按报文顺序作用，受影响成员 expires 统一为
                # t+membership_age
                _, records = mld_info
                expiry = t + membership_age
                for rtype, group, sources in records:
                    table = membership.setdefault((vlan, group), {})
                    apply_v2_record(
                        table, port_name, rtype, sources, expiry
                    )
                    if not table:
                        del membership[(vlan, group)]
                routers = [
                    name for name in eligible if name in router_set
                ]
                egress = routers if routers else eligible
                action = "mldv2_report"
            elif mld_info is not None:  # 合法 MLDv1 控制帧
                _, mtype, group = mld_info
                if mtype == MLD_TYPE_REPORT_V1:
                    membership.setdefault((vlan, group), {})[port_name] = (
                        t + membership_age
                    )
                    routers = [
                        name for name in eligible if name in router_set
                    ]
                    egress = routers if routers else eligible
                    action = "mld_report"
                elif mtype == MLD_TYPE_DONE_V1:
                    table = membership.get((vlan, group))
                    if table is not None:  # Done 立即删除入端口成员
                        table.pop(port_name, None)
                        if not table:
                            del membership[(vlan, group)]
                    routers = [
                        name for name in eligible if name in router_set
                    ]
                    egress = routers if routers else eligible
                    action = "mld_done"
                else:  # Query：始终泛洪，不改成员状态
                    egress = eligible
                    action = "mld_query"
            elif is_group:
                multicast = (
                    _ipv6_multicast_data(raw, ethertype_offset)
                    if ethertype == IPV6_ETHER_TYPE
                    else None
                )
                group = multicast[1] if multicast is not None else None
                table = (
                    membership.get((vlan, group))
                    if group is not None
                    else None
                )
                if table:  # 命中成员表：匹配源过滤的成员加路由端口
                    source = multicast[0]
                    matching = {
                        name
                        for name, entry in table.items()
                        if member_matches(entry, source)
                    }
                    targets = matching | router_set
                    egress = [
                        name for name in eligible if name in targets
                    ]
                    action = "multicast"
                else:  # 其余组播（含广播、非 IPv6、映射不一致、无成员）泛洪
                    egress = eligible
                    action = "flood"
            else:
                hit = fdb.get((vlan, dst))
                if hit is not None and hit[0] != port_name:
                    target = hit[0]
                    target_up, target_state = port_status(target, t)
                    if (
                        target_up
                        and target_state == "forwarding"
                        and vlan in by_name[target]["allowed"]
                    ):
                        egress = [target]
                        action = "unicast"
                elif hit is None:
                    egress = eligible
                    action = "flood"
        out_ports = []
        for name in egress:
            port_stats[name]["tx"] += 1
            vlan_stats[vlan]["tx"] += 1
            out_ports.append(
                {
                    "name": name,
                    "vlan": None if vlan in by_name[name]["untagged"] else vlan,
                }
            )
        if not egress:
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        entry = {"t": t, "class": cls, "action": action, "ports": out_ports}
        results.append(entry)
        if observer is not None:  # 帧项恒 applied，output 为对应结果项
            observer["items"].append(
                {"kind": "frame", "t": t, "applied": True, "output": entry}
            )
    port_order = {port["name"]: index for index, port in enumerate(ports)}
    groups = []
    # groups 按 VLAN 与 128 位组地址数值排序；成员按配置端口序；v1 成员
    # 保持 name/expires 键形，v2 成员按 name/expires/mode/sources 固定键序，
    # 源地址按 128 位数值升序，IPv6 地址使用确定的小写压缩形式
    for vlan, group in sorted(
        membership,
        key=lambda key: (key[0], int.from_bytes(key[1], "big")),
    ):
        table = membership[(vlan, group)]
        members = []
        for name in sorted(table, key=lambda value: port_order[value]):
            entry = table[name]
            if isinstance(entry, dict):
                sources = [
                    _format_ipv6(source)
                    for source in sorted(
                        entry["sources"],
                        key=lambda value: int.from_bytes(value, "big"),
                    )
                ]
                members.append(
                    {
                        "name": name,
                        "expires": entry["expires"],
                        "mode": entry["mode"],
                        "sources": sources,
                    }
                )
            else:
                members.append({"name": name, "expires": entry})
        groups.append(
            {"vlan": vlan, "group": _format_ipv6(group), "members": members}
        )
    return {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
                "good": port_stats[port["name"]]["good"],
                "runt": port_stats[port["name"]]["runt"],
                "giant": port_stats[port["name"]]["giant"],
                "alignment": port_stats[port["name"]]["alignment"],
                "bad_fcs": port_stats[port["name"]]["bad_fcs"],
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
        "groups": groups,
    }


STORM_CHECK_CONFIG_KEYS = frozenset(
    ("bridges", "links", "delay", "bridge", "ports", "age", "storm",
     "max_frame")
)


QOS_DECODE_FRAME_KEYS = FRAME_DECODE_FRAME_KEYS  # {"t", "port", "data"}


def validate_qos_decode_events(events, ports, link_ids, lags):
    """qos-decode 事件：链路/成员/service 项与 t/port/data 原始帧按 t 非降混合。

    非帧项沿用 qos-check；帧子序列复用 forward-decode 全量校验（hex、
    最短长度、单层 8100、双标签拒绝、目的非全零、源非零单播），再在混合
    序上重放跨类型的 t 非降。
    """
    if not isinstance(events, list):

def _result_bytes(result):
    """stdout 载荷：紧凑 UTF-8 JSON 加一个 LF。"""
    return (
        json.dumps(result, ensure_ascii=False, separators=(",", ":")).encode(
            "utf-8"
        )
        + b"\n"
    )


def _cmd_record(
    config_path,
    events_path,
    log_path,
    max_events,
    max_log_bytes,
    max_config_bytes,
    max_events_bytes,
    max_output_bytes,
    max_record_work,
):
    try:
        with open(config_path, "rb") as config_handle, open(
            events_path, "rb"
        ) as events_handle:
            # 两文件均可读后，先判 CONFIG 原始字节，再判 EVENTS 原始字节
            config_raw = _read_limited(config_handle, max_config_bytes)
            if config_raw is None:
                _fail("config_limit")
                return 5
            events_raw = _read_limited(events_handle, max_events_bytes)
            if events_raw is None:
                _fail("events_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        # 事件上界先于解析与预演判定；超限时绝不触碰 LOG
        events_preview = parse_json(events_raw)
        if isinstance(events_preview, list) and len(events_preview) > max_events:
            _fail("event_limit")
            return 5
        # 先无副作用预演：解析、全部校验与各重载点检测均在内存完成；
        # 工作量预演在语义校验后、正式仿真与 LOG 构造前，超限绝不触碰 LOG
        config = parse_json(config_raw)
        events = events_preview
        mode = _log_mode(config, events)
        if mode == "fdb":
            result, observer = _run_fdb(
                config, events, True, max_record_work
            )
        elif mode == "stp":
            result, observer = _run_stp(
                config, events, True, max_record_work
            )
        elif mode == "loop":
            result, observer = _run_loop_detect(
                config, events, True, max_record_work
            )

            result, observer = _run_forward_check(
                config, events, True, max_record_work
            )
        elif mode == "stp_decode":
            result, observer = _run_stp_decode(
                config, events, True, max_record_work
            )
        elif mode == "igmp_snoop_decode":
            result, observer = _run_igmp_snoop_decode(
                config, events, True, max_record_work
            )
        elif mode == "mld_snoop_decode":
            result, observer = _run_mld_snoop_decode(
                config, events, True, max_record_work
            )
        elif mode == "stp_check":
            result, observer = _run_stp_check(
                config, events, True, max_record_work
            )
        elif mode == "forward_stp_storm":
            result, observer = _run_forward_stp_storm(
                config, events, True, max_record_work
            )
        elif mode == "lag":
            result, observer = _run_lag(
                config, events, True, max_record_work
            )
        elif mode == "mirror":
            result, observer = _run_mirror(
                config, events, True, max_record_work
            )
        elif mode == "acl":
            result, observer = _run_acl(
                config, events, True, max_record_work
            )
        elif mode == "security_check":
            result, observer = _run_security_check(
                config, events, True, max_record_work
            )
        elif mode == "acl_check":
            result, observer = _run_acl_check(
                config, events, True, max_record_work
            )
        elif mode == "qos":
            result, observer = _run_qos(
                config, events, True, max_record_work
            )
        elif mode == "qos_check":
            result, observer = _run_qos_check(
                config, events, True, max_record_work
            )
        elif mode == "qos_decode":
            result, observer = _run_qos_decode(
                config, events, True, max_record_work
            )
        elif mode == "qos_wire_decode":
            result, observer = _run_qos_wire_decode(
                config, events, True, max_record_work
            )
        elif mode == "qos_pfc_decode":
            result, observer = _run_qos_pfc_decode(
                config, events, True, max_record_work
            )
        elif mode == "mirror_check":
            result, observer = _run_mirror_check(
                config, events, True, max_record_work
            )
        elif mode == "lag_check":
            result, observer = _run_lag_check(
                config, events, True, max_record_work
            )
        elif mode == "storm_check":
            result, observer = _run_storm_check(
                config, events, True, max_record_work
            )
        else:
            result, observer = _run_reload(
                config, events, True, max_record_work
            )
        doc = _build_log_doc(
