class IgmpSnoopCase(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        d = self.tmp.name
        self.cfg = os.path.join(d, "config.json")
        self.evt = os.path.join(d, "events.json")
        self.log = os.path.join(d, "out.log")

    def tearDown(self):
        self.tmp.cleanup()

    def write(self, config, events):
        with open(self.cfg, "wb") as handle:
            handle.write(json.dumps(config).encode())
        with open(self.evt, "wb") as handle:
            handle.write(json.dumps(events).encode())

    def run_cmd(self, *args):
        proc = subprocess.run(
            [sys.executable, SWITCH, *args],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
        )
        return proc.returncode, proc.stdout, proc.stderr

    def simulate(self, config, events):
        self.write(config, events)
        code, out, err = self.run_cmd(
            "igmp-snoop-decode", self.cfg, self.evt
        )
        self.assertEqual(code, 0, err)
        return json.loads(out.decode())

    def report(self, t, port, group, vlan=1, bad_fcs=False, **kwargs):
        return raw_frame(
            t, port, group_mac(group), "02:00:00:00:00:01",
            ipv4_igmp(0x16, group, **kwargs), vlan=vlan, bad_fcs=bad_fcs,
        )

    def leave(self, t, port, group, vlan=1, **kwargs):
        return raw_frame(
            t, port, group_mac(group), "02:00:00:00:00:01",
            ipv4_igmp(0x17, group, **kwargs), vlan=vlan,
        )

    def query(self, t, port, group=(224, 0, 0, 1), vlan=1, **kwargs):
        return raw_frame(
            t, port, group_mac(group), "02:00:00:00:00:fe",
            ipv4_igmp(0x11, group, **kwargs), vlan=vlan,
        )

    def data_frame(self, t, port, group, src="02:00:00:00:00:09",
                   vlan=1, dst=None, payload=None):
        return raw_frame(
            t, port, dst if dst is not None else group_mac(group), src,
            payload if payload is not None else ipv4_udp_like(group),
            vlan=vlan,
        )

    def data_frame_src(self, t, port, group, src_ip, vlan=1):
        """源 IPv4 地址可控的组播数据帧。"""
        return raw_frame(
            t, port, group_mac(group), "02:00:00:00:00:09",
            ipv4_udp_like(group, src=src_ip), vlan=vlan,
        )

    def v3_report(self, t, port, records, vlan=1, **kwargs):
        return raw_frame(
            t, port, "01:00:5e:00:00:16", "02:00:00:00:00:02",
            ipv4_igmp_v3(records, **kwargs), vlan=vlan,
        )


class IgmpControlTest(IgmpSnoopCase):
    def test_report_to_router_only_and_member_delivery(self):
        # Report 仅发往同 VLAN 可转发路由端口 p1（trunk，带标签）；
        # 随后组成员数据发往成员 p2 与路由 p1，排除入端口 p3
        config = make_config(router_ports=("p1",))
        events = [
            self.report(1, "p2", G1),
            self.data_frame(2, "p3", G1, src="02:00:00:00:00:09"),
        ]
        result = self.simulate(config, events)
        actions = [(r["t"], r["action"]) for r in result["results"]]
        self.assertEqual(actions, [(1, "igmp_report"), (2, "multicast")])
        self.assertEqual(
            result["results"][0]["ports"], [{"name": "p1", "vlan": 1}]
        )
        # trunk 端口均保留标签（vlan=1）
        self.assertEqual(
            result["results"][1]["ports"],
            [{"name": "p1", "vlan": 1}, {"name": "p2", "vlan": 1}],
        )

    def test_member_delivery_untagged_semantics(self):
        # 成员端口 p4 为 hybrid 且 vlan1 在 untagged：输出去标签（null）
        config = make_config(router_ports=("p1",))
        events = [
            self.report(1, "p4", G1),
            self.data_frame(2, "p3", G1, src="02:00:00:00:00:09"),
        ]
        result = self.simulate(config, events)
        self.assertEqual(
            result["results"][1]["ports"],
            [{"name": "p1", "vlan": 1}, {"name": "p4", "vlan": None}],
        )

    def test_report_floods_without_eligible_router(self):
        # 无路由端口时 Report 泛洪（排除入端口），动作仍为 igmp_report
        config = make_config(router_ports=())
        events = [self.report(1, "p2", G1)]
        result = self.simulate(config, events)
        self.assertEqual(result["results"][0]["action"], "igmp_report")
        self.assertEqual(
            [p["name"] for p in result["results"][0]["ports"]],
            ["p1", "p3", "p4"],
        )

def _validate_log_shape(log):
    """严格校验 LOG 字段、类型、键序；不含语义重放。"""
    if not isinstance(log, dict) or list(log) != list(LOG_KEYS):
        raise InvalidInput("bad log")
    if not _is_int(log["schema"]) or log["schema"] != RECORD_SCHEMA:
        raise InvalidInput("bad log schema")
    config = log["config"]
    if not isinstance(config, dict):
        raise InvalidInput("bad log config")
    _assert_canonical_order(config)
    records = log["records"]
    if not isinstance(records, list):
        raise InvalidInput("bad log records")
    for record in records:
        if not isinstance(record, dict) or list(record) != list(RECORD_KEYS):
            raise InvalidInput("bad log record")
        if not _is_int(record["t"]) or record["t"] < 0:
            raise InvalidInput("bad log t")
        if not _is_int(record["version"]) or record["version"] < 0:
            raise InvalidInput("bad log version")
        event = record["event"]
        if not isinstance(event, dict):
            raise InvalidInput("bad log event")
        _assert_canonical_order(event)
        _event_kind(event)
        if not isinstance(record["applied"], bool):
            raise InvalidInput("bad log applied")
        # output 通常为对象或 null；link-wire 模式下为结果对象数组（可为
        # 空数组）。语义重放再逐项核对其精确值。
        if record["output"] is not None and not isinstance(
            record["output"], (dict, list)
        ):
            raise InvalidInput("bad log output")
    digest = log["sha256"]
    if not isinstance(digest, str) or _HEX64_RE.fullmatch(digest) is None:
        raise InvalidInput("bad log sha256")


def _verify_records(log, events, items):
    """重放后逐项核对 t/version/event/applied/output。"""
    records = log["records"]
    if len(records) != len(items):
        raise InvalidInput("bad log records")
    mode = _log_mode(log["config"], events)
    version = 0
    for event, observed, record in zip(events, items, records):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log record")
        if mode in ("fdb", "stp", "loop"):
            if observed["applied"]:
                version += 1
        elif mode in (
            "link_forward", "link_wire", "link_wire_decode",
            "link_flow_decode", "qos_wire_decode", "qos_pfc_decode",
            "forward_stp",
            "stp_decode", "stp_check", "forward_stp_storm",
            "igmp_snoop_decode", "mld_snoop_decode",
        ):
            if kind == "link" and observed["applied"]:
                version += 1
        elif mode == "link_state":
            if observed["applied"]:
                version += 1
        elif mode in (
            "qos", "lag", "mirror", "acl", "security_check", "qos_check",
            "qos_decode",
            "acl_check", "mirror_check", "lag_check", "storm_check"
        ):
            if kind in ("link", "member") and observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        if record["t"] != event["t"]:
            raise InvalidInput("bad log t")
        if record["version"] != version:
            raise InvalidInput("bad log version")
        if not _json_equal(record["event"], _canonical(event)):
            raise InvalidInput("bad log event")
        if record["applied"] is not observed["applied"]:
            raise InvalidInput("bad log applied")
        if not _json_equal(record["output"], observed["output"]):
            raise InvalidInput("bad log output")


def _atomic_write(path, payload):
    """同目录临时文件 + os.replace 原子写入；失败不改动目标。"""
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_path = tempfile.mkstemp(prefix=".switch-log-", dir=directory)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
    except OSError:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def _result_bytes(result):
    """stdout 载荷：紧凑 UTF-8 JSON 加一个 LF。"""
